  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function isJson(value) {
  if (value === null) return true;
  const type = typeof value;
  if (type === 'boolean' || type === 'string') return true;
  if (type === 'number') return Number.isFinite(value);
  if (Array.isArray(value)) return value.every(isJson);
  if (type === 'object') {
    if (Object.getPrototypeOf(value) !== Object.prototype) return false;
    return Object.keys(value).every((key) => isJson(value[key]));
  }
  return false;
}

function deepClone(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(deepClone);
  const result = {};
  for (const key of Object.keys(value)) {
    Object.defineProperty(result, key, {
      value: deepClone(value[key]),
      writable: true,
      enumerable: true,
      configurable: true,
    });
  }
  return result;
}

function jsonEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return false;
  if (typeof a !== 'object') return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    return a.every((item, i) => jsonEqual(item, b[i]));
  }
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;
  return aKeys.every((key) => Object.prototype.hasOwnProperty.call(b, key) && jsonEqual(a[key], b[key]));
}

/** Locate the container that holds the last token of a pointer's tokens. */
function parentOf(root, tokens) {
  const parentTokens = tokens.slice(0, -1);
  const lastToken = tokens[tokens.length - 1];
  const parent = resolve(root, formatPointer(parentTokens));
  return { parent, lastToken, parentTokens };
}

function addAt(root, path, value) {
  const tokens = parsePointer(path);
  const cloned = deepClone(value);
  if (tokens.length === 0) return cloned;
  const { parent, lastToken, parentTokens } = parentOf(root, tokens);
  if (Array.isArray(parent)) {
    if (lastToken === '-') {
      parent.push(cloned);
    } else if (ARRAY_INDEX.test(lastToken)) {
      const index = Number(lastToken);
      if (index > parent.length) throw new PointerError(`index out of range: ${lastToken} at ${path}`, path);
      parent.splice(index, 0, cloned);
    } else {
      throw new PointerError(`invalid array index: ${lastToken} at ${path}`, path);
    }
  } else if (parent !== null && typeof parent === 'object') {
    Object.defineProperty(parent, lastToken, { value: cloned, writable: true, enumerable: true, configurable: true });
  } else {
    throw new PointerError(`cannot index into ${typeNameOf(parent)} at ${formatPointer(parentTokens)}`, path);
  }
  return root;
}

function removeAt(root, path) {
  resolve(root, path);
  const tokens = parsePointer(path);
  if (tokens.length === 0) throw new Error('cannot remove the whole document');
  const { parent, lastToken } = parentOf(root, tokens);
  if (Array.isArray(parent)) {
    parent.splice(Number(lastToken), 1);
  } else {
    delete parent[lastToken];
  }
  return root;
}

function replaceAt(root, path, value) {
  resolve(root, path);
  const tokens = parsePointer(path);
  const cloned = deepClone(value);
  if (tokens.length === 0) return cloned;
  const { parent, lastToken } = parentOf(root, tokens);
  if (Array.isArray(parent)) {
    parent[Number(lastToken)] = cloned;
  } else {
    parent[lastToken] = cloned;
  }
  return root;
}

function moveOp(root, operation) {
  const { from, path } = operation;
  if (from === path) {
    resolve(root, from);
    return root;
  }
  const fromTokens = parsePointer(from);
  const pathTokens = parsePointer(path);
  if (pathTokens.length > fromTokens.length && fromTokens.every((token, i) => token === pathTokens[i])) {
    throw new Error('cannot move a value into its own child');
  }
  const value = resolve(root, from);
  const cloned = deepClone(value);
  removeAt(root, from);
  return addAt(root, path, cloned);
}

function copyOp(root, operation) {
  const { from, path } = operation;
  const value = resolve(root, from);
  return addAt(root, path, value);
}

function testOp(root, operation) {
  const { path, value } = operation;
  const actual = resolve(root, path);
  if (!jsonEqual(actual, value)) throw new Error(`test failed at ${path}`);
  return root;
}

const VALID_OPS = ['add', 'remove', 'replace', 'move', 'copy', 'test'];

function validateAndExecute(root, operation) {
  if (typeof operation !== 'object' || operation === null || Array.isArray(operation)) {
    throw new Error('operation must be an object');
  }
  const { op } = operation;
  if (!VALID_OPS.includes(op)) throw new Error(`unknown operation: ${op}`);
  if (!('path' in operation)) throw new Error(`${op} requires a path`);
  if (op === 'add' || op === 'replace' || op === 'test') {
    if (!('value' in operation)) throw new Error(`${op} requires a value`);
    if (!isJson(operation.value)) throw new Error('value is not JSON data');
  }
  if (op === 'move' || op === 'copy') {
    if (!('from' in operation)) throw new Error(`${op} requires a from`);
  }
  const { path } = operation;
  switch (op) {
    case 'add':
      return addAt(root, path, operation.value);
    case 'remove':
      return removeAt(root, path);
    case 'replace':
      return replaceAt(root, path, operation.value);
    case 'move':
      return moveOp(root, operation);
    case 'copy':
      return copyOp(root, operation);
    case 'test':
      return testOp(root, operation);
    default:
      throw new Error(`unknown operation: ${op}`);
  }
}

/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *

diffs.oldText:
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  throw new Error('not implemented');
}

diffs.newText:
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  if (!Array.isArray(operations)) throw new Error('patch must be an array');
  if (!isJson(document)) throw new Error('document is not JSON data');
  let working = deepClone(document);
  for (let index = 0; index < operations.length; index += 1) {
    const operation = operations[index];
    try {
      working = validateAndExecute(working, operation);
    } catch (error) {
      if (error instanceof PointerError) {
        throw new PatchError(error.message, index, { cause: error });
      }
      throw new PatchError(error.message, index);
    }
  }
  return working;
}
